var a=`1002-tom-kha-gai`;var s=`world-1002`;var n=`TH`;var t=`southeast-asia`;var m=4;var h=40;var o={en:`Tom Kha Gai`,ua:`Том кха гай`};var r={en:`Tom Kha Gai is a dish from Thailand prepared with lemongrass, galangal, makrut lime leaves, chicken thigh. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Том кха гай, страва кухні країни Таїланд, яку готують із таких продуктів: лемонграс, галангал, листя макрут-лайма, куряче стегно. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 15 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 15 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:15,i:[[`chicken-stock`,900,`ml`],[`lemongrass`,3,`pcs`],[`galangal`,35,`g`],[`makrut-lime-leaves`,5,`leaf`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 20 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 20 хвилин до готовності й м’якості.`,t:[`poaching`],m:20,i:[[`chicken-thigh`,650,`g`],[`straw-mushroom`,230,`g`],[`coconut-milk`,500,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,40,`ml`],[`lime-juice`,60,`ml`],[`palm-sugar`,15,`g`],[`bird-s-eye-chili`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,20,`g`]]}];var g={slug:a,id:s,country:`TH`,region:t,servings:4,minutes:40,title:o,text:r,steps:l};export{n as country,g as default,s as id,h as minutes,t as region,m as servings,a as slug,l as steps,r as text,o as title};